commands.command:
CREATE OR REPLACE TABLE sales_abac (
  id INT,
  region STRING,
  email STRING,
  revenue INT
);

CREATE OR REPLACE TABLE customers_abac (
  customer_id INT,
  customer_name STRING,
  email STRING,
  region STRING
);

ALTER TABLE customers_abac
ALTER COLUMN email
SET TAGS ('pii' = 'email');

ALTER TABLE customers_abac
ALTER COLUMN region
SET TAGS ('access_type' = 'region');
